svg.script:
/*  */
function setTrimestre(t) {
  var root = document.getElementById('a16p7-svg');
  if (!root) return;
  root.setAttribute('data-trimestre', t);

  for (var i = 1; i <= 3; i++) {
    var tab = document.getElementById('a16p7-tab-t' + i);
    if (tab) {
      tab.setAttribute('aria-selected', i === t ? 'true' : 'false');
    }
  }
}

function setSoro(s) {
  var root = document.getElementById('a16p7-svg');
  if (!root) return;
  root.setAttribute('data-soro', s);

  var types = ['sus', 'imu', 'agu', 'duv'];
  for (var i = 0; i < types.length; i++) {
    var btn = document.getElementById('a16p7-btn-soro-' + types[i]);
    if (btn) {
      btn.setAttribute('aria-selected', types[i] === s ? 'true' : 'false');
    }
  }
}
/*  */
